"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { readMs } from "./motion";
import "./toasts.css";

export type Toast = { id: number; text: string; tone: "ok" | "error"; state: "live" | "dismiss" | "push" };

/* A new toast rises in front, older ones step back, and a fourth pushes the oldest out. */
export function useToasts() {
  const [list, setList] = useState<Toast[]>([]);
  const next = useRef(0);
  const timers = useRef(new Set<number>());

  const later = useCallback((fn: () => void, ms: number) => {
    const t = window.setTimeout(() => {
      timers.current.delete(t);
      fn();
    }, ms);
    timers.current.add(t);
  }, []);

  const drop = useCallback(
    (id: number, how: "dismiss" | "push") => {
      setList((cur) => cur.map((t) => (t.id === id && t.state === "live" ? { ...t, state: how } : t)));
      later(() => setList((cur) => cur.filter((t) => t.id !== id)), readMs("--ob-toast-close-dur", 250) + 60);
    },
    [later]
  );

  const toast = useCallback(
    (text: string, tone: "ok" | "error" = "ok") => {
      const id = ++next.current;
      setList((cur) => {
        const live = cur.filter((t) => t.state === "live");
        const out = new Set(live.slice(2).map((t) => t.id));
        if (out.size) later(() => setList((c) => c.filter((t) => !out.has(t.id))), readMs("--ob-toast-close-dur", 250) + 60);
        return [{ id, text, tone, state: "live" as const }, ...cur.map((t) => (out.has(t.id) ? { ...t, state: "push" as const } : t))];
      });
      later(() => drop(id, "dismiss"), tone === "error" ? 6000 : 2800);
    },
    [drop, later]
  );

  useEffect(() => {
    const all = timers.current;
    return () => all.forEach((t) => window.clearTimeout(t));
  }, []);

  return { list, toast, dismiss: (id: number) => drop(id, "dismiss") };
}

export function Toasts({ list, dismiss }: { list: Toast[]; dismiss: (id: number) => void }) {
  const live = list.filter((t) => t.state === "live");
  return (
    <div className="ob-toasts" aria-live="polite">
      <div className="ob-toast-stack">
        {list.map((t) => (
          <ToastBanner key={t.id} t={t} depth={Math.max(0, live.indexOf(t))} onTap={() => dismiss(t.id)} />
        ))}
      </div>
    </div>
  );
}

function ToastBanner({ t, depth, onTap }: { t: Toast; depth: number; onTap: () => void }) {
  const ref = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const el = ref.current!;
    el.classList.add("is-enter");
    void el.offsetWidth;
    el.classList.remove("is-enter");
  }, []);
  return (
    <div
      ref={ref}
      className={
        "ob-toast" +
        (t.tone === "error" ? " is-error" : "") +
        (t.state === "push" ? " is-leaving" : t.state === "dismiss" ? " is-dismiss" : "")
      }
      data-depth={t.state === "live" ? depth : undefined}
      role={t.tone === "error" ? "alert" : "status"}
      onClick={onTap}
    >
      <span className="ob-toast-dot" aria-hidden="true">
        {t.tone === "error" ? (
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            <path d="M6 3v3.5M6 9h.01" />
          </svg>
        ) : (
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M2.5 6.3l2.2 2.2L9.5 3.7" />
          </svg>
        )}
      </span>
      <span className="ob-toast-text">{t.text}</span>
    </div>
  );
}

/* Toasts: the newest in front, older ones stepping back behind it. Dark on a
   light page and the other way round. Sits above a bottom dock; move it
   with --ob-toasts-bottom. */

:where(:root) {
  --ob-toast-open-dur: 420ms;
  --ob-toast-close-dur: 250ms;
  --ob-toast-step: 10px;
}

.ob-toasts {
  position: fixed; left: var(--ds-space-md); right: var(--ds-space-md); z-index: var(--ds-z-toast);
  bottom: var(--ob-toasts-bottom, calc(env(safe-area-inset-bottom) + 96px));
  display: flex; justify-content: center; pointer-events: none;
}
/* Every toast sits in the same grid cell, so the stack is as tall as the
   front one and the rest tuck in behind it. */
.ob-toast-stack { display: grid; width: 100%; max-width: 400px; }
.ob-toast {
  grid-area: 1 / 1; align-self: end;
  display: flex; align-items: center; gap: var(--ds-space-xs);
  padding: var(--ds-space-sm) var(--ds-space-md) var(--ds-space-sm) var(--ds-space-sm);
  border-radius: var(--ds-radius-lg);
  background: var(--ds-color-text); color: var(--ds-color-bg);
  box-shadow: var(--ob-shadow-float, var(--ds-shadow-lg));
  font-weight: var(--ds-weight-semibold); font-size: var(--ds-type-ui-size);
  pointer-events: auto; cursor: pointer;
  transform-origin: 50% 0;
  transition:
    translate var(--ob-toast-open-dur) var(--ds-ease-out),
    scale var(--ob-toast-open-dur) var(--ds-ease-out),
    opacity var(--ob-toast-open-dur) var(--ds-ease-out),
    filter var(--ob-toast-open-dur) var(--ds-ease-out);
}
.ob-toast[data-depth="0"] { z-index: 3; }
.ob-toast[data-depth="1"] { z-index: 2; translate: 0 calc(var(--ob-toast-step) * -1); scale: 0.95; opacity: 0.85; }
.ob-toast[data-depth="2"] { z-index: 1; translate: 0 calc(var(--ob-toast-step) * -2); scale: 0.9; opacity: 0.6; }
.ob-toast[data-depth="1"] > *, .ob-toast[data-depth="2"] > * { opacity: 0; }

.ob-toast.is-enter { translate: 0 24px; scale: 0.96; opacity: 0; transition: none; }
.ob-toast.is-dismiss,
.ob-toast.is-leaving {
  opacity: 0; filter: blur(2px);
  transition:
    translate var(--ob-toast-close-dur) var(--ds-ease-in),
    scale var(--ob-toast-close-dur) var(--ds-ease-in),
    opacity var(--ob-toast-close-dur) var(--ds-ease-in),
    filter var(--ob-toast-close-dur) var(--ds-ease-in);
}
.ob-toast.is-dismiss { translate: 0 16px; }
.ob-toast.is-leaving { translate: 0 calc(var(--ob-toast-step) * -3); scale: 0.85; }

.ob-toast-dot {
  width: 24px; height: 24px; flex: none; display: grid; place-items: center;
  border-radius: var(--ds-radius-full); background: var(--ds-color-success); color: var(--ds-color-accent-contrast);
}
.ob-toast.is-error .ob-toast-dot { background: var(--ds-color-danger); }
.ob-toast-text { min-width: 0; }

@media (prefers-reduced-motion: reduce) {
  .ob-toast { transition: opacity var(--ds-duration-fast) linear !important; translate: none !important; scale: none !important; }
}
